// -----------------------------------------------------------------------------
// ssv_audio_debug_overlay.sv -- GENERATED by scratchpad gen_overlay.py.
//
// Fullscreen ES5506 audio-debug text screen. Replaces the game picture (the
// core keeps running underneath, video pipeline untouched) with a black
// screen carrying every audio-path observable needed to root-cause warped
// music/SFX: per-voice register shadows (CR/FC/ACCUM/START/END/VOL/ECOUNT/
// K1/K2) captured at the engine's own eng_snap, per-frame event counters
// (sample ticks, underruns, host writes/reads, register commits, IRQ sets),
// SDRAM p4 fetch latency stats (last/max/frame-max plus >64/>128/>256-cycle
// bucket counts), output L/R levels with per-frame min/max (clipping check),
// a 32-bit running-voice mask, and a 12-entry newest-first host commit log.
//
// Grid: 84x40 cells of 4x6 px (3x5 glyph) over the 336x240 active raster.
// All display values are latched at frame start so a screenshot is coherent.
// -----------------------------------------------------------------------------

module ssv_audio_debug_overlay (
    input  logic        clk,
    input  logic        rst,
    input  logic        en,

    // raster position from ssv_video_timing (active region starts at 0,0)
    input  logic        ce_pixel,
    input  logic [8:0]  hcnt,
    input  logic [8:0]  vcnt,
    input  logic [8:0]  active_width,
    input  logic [8:0]  active_height,
    input  logic [23:0] rgb_in,
    output logic [23:0] rgb_out,

    // engine snapshot bus (regs -> voice engine, valid on eng_snap)
    input  logic        eng_snap,
    input  logic [4:0]  eng_voice,
    input  logic [15:0] eng_cr,
    input  logic [16:0] eng_fc,
    input  logic [31:0] eng_accum,
    input  logic [31:0] eng_start,
    input  logic [31:0] eng_end,
    input  logic [15:0] eng_lvol,
    input  logic [15:0] eng_rvol,
    input  logic [8:0]  eng_ecount,
    input  logic [15:0] eng_k1,
    input  logic [15:0] eng_k2,

    // engine writeback pulses (voice -> regs), for the race detectors
    input  logic        eng_wr_accum,
    input  logic [31:0] eng_accum_w,
    input  logic        eng_wr_cr,
    input  logic        eng_wr_filt,
    input  logic        eng_wr_env,
    // which ES5506 CR banks this cartridge populates (cfg.bank_valid)
    input  logic [3:0]  bank_valid,

    // engine / IRQ events
    input  logic        sample_tick,
    input  logic        underrun,
    input  logic        irq_n,
    input  logic        irq_set,
    input  logic [4:0]  irq_voice,
    input  logic [4:0]  active_voices,
    input  logic [6:0]  current_page,

    // host interface activity
    input  logic        commit,
    input  logic [6:0]  commit_page,
    input  logic [3:0]  commit_reg,
    input  logic [31:0] commit_data,
    input  logic        host_we,
    input  logic        host_re,
    input  logic        ce_snd,

    // sample-fetch SDRAM port (p4)
    input  logic        p4_req,
    input  logic        p4_ack,

    // final mix
    input  logic signed [15:0] audio_l,
    input  logic signed [15:0] audio_r
);

// ---------------------------------------------------------------------------
// Per-voice register shadow, written on the engine's own snapshot pulse so it
// always reflects exactly what the voice engine consumed (accum is written
// back by the engine every sample, so this shows the live phase accumulator).
// ---------------------------------------------------------------------------
localparam int REC_W = 202;
logic [REC_W-1:0] shadow [0:31];
always_ff @(posedge clk) begin
    if (eng_snap)
        shadow[eng_voice] <= {eng_cr, eng_fc, eng_accum, eng_start, eng_end,
                              eng_lvol, eng_rvol, eng_ecount, eng_k1, eng_k2};
end

logic [4:0]       shadow_rd_addr;
logic [REC_W-1:0] shadow_q;
always_ff @(posedge clk) shadow_q <= shadow[shadow_rd_addr];

// ---------------------------------------------------------------------------
// Running-voice mask (CR STOP0|STOP1 both clear) captured per snapshot.
// ---------------------------------------------------------------------------
logic [31:0] run_mask;
always_ff @(posedge clk) begin
    if (rst) run_mask <= 32'd0;
    else if (eng_snap) run_mask[eng_voice] <= ~(eng_cr[0] | eng_cr[1]);
end

// ---------------------------------------------------------------------------
// Audio-race detectors. One counter/latch per corruption scenario from the
// 2026-08-26 audio-path audit, so a single gameplay video attributes the
// warped-sound events to a mechanism:
//
//  TP  teleport: at eng_snap the voice's ACCUM differs from the engine's own
//      last writeback with no intervening host ACCUM commit -- a lost or
//      corrupted register-file write (MLAB RDW garbage, dropped deferral).
//      Latches voice, expected, seen, frame.
//  RA  runaway: running voice snapshotted with ACCUM outside [START,END] --
//      the audible warped-fragment state itself (stuck LEI, teleport
//      aftermath). Latches voice, CR, ACCUM, frame.
//  F1  host commit to an UNPROTECTED field (FC/LVRAMP/RVRAMP/K2RAMP/K1RAMP
//      of bank0, START/END/ACCUM of bank1) of the voice being snapshotted,
//      landing exactly in the MLAB read-during-write window (commit pulse
//      coincides with eng_snap). Cause condition for TP. Latches
//      voice/reg/bank/frame.
//  F2  host CR commit to the in-flight voice between its snapshot and the
//      engine's CR writeback that same scan -- stale loop-transition masks
//      merge over the fresh CR. Latches frame.
//  CS  CR commit adjacent to the voice's own snapshot (the cr_snap_missed /
//      voided-scan engagement rate -- benign by design, baseline for F2).
//  F3  eng_snap inside a host read-steal window (flush/hold hazards).
//  F4  as F3 but with a same-voice commit 1-3 cycles earlier (stale-_h
//      fresh-bit hole).
//  DF  host commit coinciding with an engine writeback pulse (deferral
//      machinery engagement; a skid overflow would silently drop here).
//  CX  snapshot CR with LEI set while LPE/BLE still set -- illegal merge
//      signature of the stale-mask class.
//  BK  running voice whose CR selects an unpopulated sample bank -- CR
//      corruption signature (silent/wrong voice).
//  SE  running forward voice with START > END -- register-pair corruption.
//  PQ  snapshots with CR.IRQ pending (promotion backlog indicator).
// ---------------------------------------------------------------------------
logic [31:0] exp_accum [0:31];
logic [31:0] exp_valid;
logic [31:0] acc_dirty;

logic [15:0] det_tp_cnt,  det_ra_cnt,  det_f1_cnt, det_f2_cnt;
logic [15:0] det_cs_cnt,  det_f3_cnt,  det_f4_cnt, det_df_cnt;
logic [15:0] det_cx_cnt,  det_bk_cnt,  det_se_cnt, det_pq_cnt;
logic [4:0]  det_tp_voice, det_ra_voice, det_f1_voice;
logic [31:0] det_tp_exp, det_tp_seen, det_ra_accum;
logic [15:0] det_ra_cr;
logic [3:0]  det_f1_reg;
logic        det_f1_bank;
logic [15:0] det_tp_frame, det_ra_frame, det_f1_frame, det_f2_frame;

// Second-pass discriminators (2026-08-27 video: TP bursts correlate exactly
// with the audible corruption but F1/F2/F4/DF stayed zero, so the corruption
// is either computed by the engine from a garbage snapshot or lands in the
// wrong MLAB word; these split the space):
//  F0  commit pulse one cycle AFTER a snap (write edge == snapshot latch
//      edge, the same-edge RDW variant F1's window misses).
//  WJ  writeback jump: eng_wr_accum whose value matches none of the six
//      legal advance/wrap/reflect forms of the snapshot accum -- the engine
//      COMPUTED the teleport (garbage snapshot bounds). Latches voice,
//      snapshot accum, written accum, and the snapshot START/END that fed
//      the math. A TP without a matching WJ = storage-side corruption
//      (wrong-address write / dropped write) instead.
//  AC  host ACCUM commit count + last voice/data -- distinguishes lost
//      note-on writes (new bounds, stale accum, AC shows the write existed).
logic [15:0] det_f0_cnt, det_wj_cnt, det_ac_cnt;
logic [4:0]  det_wj_voice;
logic [31:0] det_wj_snap, det_wj_new, det_wj_start, det_wj_end;
logic [4:0]  det_ac_voice;
logic [31:0] det_ac_data;
logic        snap_d1;

logic        f2_arm;
logic [4:0]  f2_voice;
logic        re_d1, re_d2, re_d3;
logic        cvm_d1, cvm_d2, cvm_d3;
logic        eng_write_any_d1;

wire commit_vmatch = commit && (commit_page < 7'h40);
wire [4:0] commit_voice = commit_page[4:0];
wire commit_accum   = commit_vmatch &&  commit_page[5] && (commit_reg == 4'h3);
wire commit_cr      = commit_vmatch && (commit_reg == 4'h0);
// Fields with neither host_fresh protection nor engine ownership: FC(1),
// LVRAMP(3), RVRAMP(5), K2RAMP(8), K1RAMP(A) on bank0; START(1), END(2),
// ACCUM(3) on bank1. A garbage snapshot of any of these can propagate into a
// persistent engine writeback of another field.
wire commit_f1reg = commit_vmatch &&
    (commit_page[5]
        ? (commit_reg == 4'h1 || commit_reg == 4'h2 || commit_reg == 4'h3)
        : (commit_reg == 4'h1 || commit_reg == 4'h3 || commit_reg == 4'h5 ||
           commit_reg == 4'h8 || commit_reg == 4'ha));
wire commit_this_voice = commit_vmatch && (commit_voice == eng_voice);

wire snap_running  = ~(eng_cr[0] | eng_cr[1]);
wire snap_outrange = snap_running &&
                     ((eng_accum > eng_end) || (eng_accum < eng_start));
wire eng_write_any = eng_wr_accum | eng_wr_cr | eng_wr_filt | eng_wr_env;
wire read_window   = host_re || re_d1 || re_d2 || re_d3;

// The six legal next-accum forms for this voice's snapshot (forward advance,
// forward loop wrap, forward reflect, and the reverse three). eng_accum and
// eng_fc still carry the in-flight voice's snapshot when eng_wr_accum pulses
// (the engine holds its slot through S_MIX).
wire [31:0] wj_fwd  = eng_accum + {15'd0, eng_fc};
wire [31:0] wj_rev  = eng_accum - {15'd0, eng_fc};
wire [31:0] wj_fwrp = eng_start + (wj_fwd - eng_end);
wire [31:0] wj_frfl = eng_end - (wj_fwd - eng_end);
wire [31:0] wj_rwrp = eng_end - (eng_start - wj_rev);
wire [31:0] wj_rrfl = eng_start + (eng_start - wj_rev);
wire wj_legal = (eng_accum_w == wj_fwd)  || (eng_accum_w == wj_rev)  ||
                (eng_accum_w == wj_fwrp) || (eng_accum_w == wj_frfl) ||
                (eng_accum_w == wj_rwrp) || (eng_accum_w == wj_rrfl) ||
                (eng_accum_w == eng_accum);
// live frame number (disp_frame increments once per frame below)
wire [15:0] frame_lo = disp_frame[15:0];

always_ff @(posedge clk) begin
    re_d1 <= host_re; re_d2 <= re_d1; re_d3 <= re_d2;
    cvm_d1 <= commit_this_voice; cvm_d2 <= cvm_d1; cvm_d3 <= cvm_d2;
    snap_d1 <= eng_snap;
    eng_write_any_d1 <= eng_write_any;
    if (rst) begin
        exp_valid <= '0; acc_dirty <= '0;
        det_tp_cnt <= '0; det_ra_cnt <= '0; det_f1_cnt <= '0; det_f2_cnt <= '0;
        det_cs_cnt <= '0; det_f3_cnt <= '0; det_f4_cnt <= '0; det_df_cnt <= '0;
        det_cx_cnt <= '0; det_bk_cnt <= '0; det_se_cnt <= '0; det_pq_cnt <= '0;
        det_tp_voice <= '0; det_ra_voice <= '0; det_f1_voice <= '0;
        det_tp_exp <= '0; det_tp_seen <= '0; det_ra_accum <= '0;
        det_ra_cr <= '0; det_f1_reg <= '0; det_f1_bank <= 1'b0;
        det_tp_frame <= '0; det_ra_frame <= '0;
        det_f1_frame <= '0; det_f2_frame <= '0;
        f2_arm <= 1'b0; f2_voice <= '0;
        det_f0_cnt <= '0; det_wj_cnt <= '0; det_ac_cnt <= '0;
        det_wj_voice <= '0; det_wj_snap <= '0; det_wj_new <= '0;
        det_wj_start <= '0; det_wj_end <= '0;
        det_ac_voice <= '0; det_ac_data <= '0;
    end else begin
        // F0: commit write edge coincides with the previous cycle's snapshot
        // latch edge (the same-edge RDW variant).
        if (snap_d1 && (commit_f1reg || commit_accum || commit_cr))
            det_f0_cnt <= det_f0_cnt + 1'd1;

        // WJ: engine-computed accum jump (snapshot bounds were garbage).
        if (eng_wr_accum && !wj_legal) begin
            det_wj_cnt   <= det_wj_cnt + 1'd1;
            det_wj_voice <= eng_voice;
            det_wj_snap  <= eng_accum;
            det_wj_new   <= eng_accum_w;
            det_wj_start <= eng_start;
            det_wj_end   <= eng_end;
        end

        // AC: host ACCUM commits (lost-note-on discriminator).
        if (commit_accum) begin
            det_ac_cnt   <= det_ac_cnt + 1'd1;
            det_ac_voice <= commit_voice;
            det_ac_data  <= commit_data;
        end
        // --- TP arm: remember the engine's own last ACCUM writeback. The
        // regs file drops that writeback when the host refreshed ACCUM since
        // the snapshot (host_fresh), so mirror that window with acc_dirty and
        // do not arm from a writeback the regs file will discard.
        if (eng_wr_accum && !acc_dirty[eng_voice]) begin
            exp_accum[eng_voice] <= eng_accum_w;
            exp_valid[eng_voice] <= 1'b1;
        end

        if (eng_snap) begin
            acc_dirty[eng_voice] <= 1'b0;

            // --- TP check ---
            if (exp_valid[eng_voice] &&
                (eng_accum != exp_accum[eng_voice])) begin
                det_tp_cnt   <= det_tp_cnt + 1'd1;
                det_tp_voice <= eng_voice;
                det_tp_exp   <= exp_accum[eng_voice];
                det_tp_seen  <= eng_accum;
                det_tp_frame <= frame_lo;
                exp_valid[eng_voice] <= 1'b0; // one event per divergence
            end

            // --- RA / CX / BK / SE / PQ state checks ---
            if (snap_outrange) begin
                det_ra_cnt   <= det_ra_cnt + 1'd1;
                det_ra_voice <= eng_voice;
                det_ra_cr    <= eng_cr;
                det_ra_accum <= eng_accum;
                det_ra_frame <= frame_lo;
            end
            if (eng_cr[2] && (eng_cr[3] || eng_cr[4]))
                det_cx_cnt <= det_cx_cnt + 1'd1;
            if (snap_running && !bank_valid[eng_cr[15:14]])
                det_bk_cnt <= det_bk_cnt + 1'd1;
            if (snap_running && !eng_cr[6] && (eng_start > eng_end))
                det_se_cnt <= det_se_cnt + 1'd1;
            if (eng_cr[7])
                det_pq_cnt <= det_pq_cnt + 1'd1;

            // --- F1: unprotected-field commit in the RDW window ---
            if (commit_f1reg && (commit_voice == eng_voice)) begin
                det_f1_cnt   <= det_f1_cnt + 1'd1;
                det_f1_voice <= commit_voice;
                det_f1_reg   <= commit_reg;
                det_f1_bank  <= commit_page[5];
                det_f1_frame <= frame_lo;
            end

            // --- CS: snap-adjacent CR commit (voided-scan engagement) ---
            if (commit_cr && (commit_voice == eng_voice))
                det_cs_cnt <= det_cs_cnt + 1'd1;

            // --- F3/F4: snapshot inside a read-steal window ---
            if (read_window) begin
                det_f3_cnt <= det_f3_cnt + 1'd1;
                if (commit_this_voice || cvm_d1 || cvm_d2 || cvm_d3)
                    det_f4_cnt <= det_f4_cnt + 1'd1;
            end

            // new scan: disarm the F2 tracker for the previous voice
            f2_arm <= 1'b0;
        end

        // --- F2: CR commit to the in-flight voice, then an engine CR
        //     writeback in the same scan (stale transition over fresh CR).
        if (commit_cr && (commit_voice == eng_voice) && !eng_snap) begin
            f2_arm   <= 1'b1;
            f2_voice <= commit_voice;
        end
        if (eng_wr_cr && f2_arm && (f2_voice == eng_voice)) begin
            det_f2_cnt   <= det_f2_cnt + 1'd1;
            det_f2_frame <= frame_lo;
            f2_arm       <= 1'b0;
        end

        // --- DF: commit racing an engine writeback (deferral engagement).
        //     The collision happens on the host_commit cycle, one cycle
        //     before the registered `commit` pulse -- compare against the
        //     delayed writeback flag or every real collision reads as zero.
        if (commit && eng_write_any_d1)
            det_df_cnt <= det_df_cnt + 1'd1;

        // host ACCUM commit supersedes the engine's remembered writeback
        if (commit_accum) begin
            exp_valid[commit_voice] <= 1'b0;
            acc_dirty[commit_voice] <= 1'b1;
        end
    end
end

// ---------------------------------------------------------------------------
// Event edge detects (some taps are level-held).
// ---------------------------------------------------------------------------
logic under_q, hostwe_q, hostre_q;
always_ff @(posedge clk) begin
    under_q  <= underrun;
    hostwe_q <= host_we;
    hostre_q <= host_re;
end
wire under_edge  = underrun && !under_q;
wire hostwe_edge = host_we  && !hostwe_q;
wire hostre_edge = host_re  && !hostre_q;

// ---------------------------------------------------------------------------
// p4 fetch latency: count clk cycles a request waits for its ack.
// ---------------------------------------------------------------------------
logic [15:0] lat_cnt;
wire p4_done = p4_req && p4_ack;
always_ff @(posedge clk) begin
    if (rst)          lat_cnt <= 16'd0;
    else if (p4_done) lat_cnt <= 16'd0;
    else if (p4_req && !(&lat_cnt)) lat_cnt <= lat_cnt + 1'd1;
end
wire [15:0] lat_now = (&lat_cnt) ? lat_cnt : lat_cnt + 1'd1;

// ---------------------------------------------------------------------------
// Frame-accumulated counters, latched into disp_* at frame start.
// ---------------------------------------------------------------------------
wire frame_pulse = ce_pixel && (hcnt == 9'd0) && (vcnt == 9'd0);

logic [15:0] c_ticks, c_under, c_commit, c_hostwr, c_hostrd, c_iset;
logic [23:0] c_cesnd, c_p4req;
logic [15:0] c_g64, c_g128, c_g256, c_latmaxf;
logic [31:0] t_under, t_p4, t_tick;
logic [15:0] latmax_sticky, lat_last;
logic signed [15:0] c_lmin, c_lmax, c_rmin, c_rmax;
logic [4:0]  last_irq_voice;

logic [31:0] disp_frame;
logic [15:0] disp_ticks, disp_under, disp_commit, disp_hostwr, disp_hostrd,
             disp_iset, disp_g64, disp_g128, disp_g256, disp_latmaxf;
logic [23:0] disp_cesnd, disp_p4req;
logic [31:0] disp_undert, disp_p4tot, disp_ticktot, disp_run;
logic [15:0] disp_al, disp_ar, disp_lmin, disp_lmax, disp_rmin, disp_rmax;
logic [4:0]  disp_av, disp_irqv;
logic [6:0]  disp_pg;
logic        disp_irqn;

// Detector panel display copies (latched per frame so video frames are
// tear-free; the underlying counters are cumulative and monotonic).
logic [15:0] dd_tp_cnt, dd_ra_cnt, dd_f1_cnt, dd_f2_cnt;
logic [15:0] dd_cs_cnt, dd_f3_cnt, dd_f4_cnt, dd_df_cnt;
logic [15:0] dd_cx_cnt, dd_bk_cnt, dd_se_cnt, dd_pq_cnt;
logic [4:0]  dd_tp_voice, dd_ra_voice, dd_f1_voice;
logic [31:0] dd_tp_exp, dd_tp_seen, dd_ra_accum;
logic [15:0] dd_ra_cr;
logic [3:0]  dd_f1_reg;
logic        dd_f1_bank;
logic [15:0] dd_tp_frame, dd_ra_frame, dd_f1_frame, dd_f2_frame;
logic [15:0] dd_f0_cnt, dd_wj_cnt, dd_ac_cnt;
logic [4:0]  dd_wj_voice, dd_ac_voice;
logic [31:0] dd_wj_snap, dd_wj_new, dd_wj_start, dd_wj_end, dd_ac_data;

always_ff @(posedge clk) begin
    if (rst) begin
        dd_tp_cnt <= '0; dd_ra_cnt <= '0; dd_f1_cnt <= '0; dd_f2_cnt <= '0;
        dd_cs_cnt <= '0; dd_f3_cnt <= '0; dd_f4_cnt <= '0; dd_df_cnt <= '0;
        dd_cx_cnt <= '0; dd_bk_cnt <= '0; dd_se_cnt <= '0; dd_pq_cnt <= '0;
        dd_tp_voice <= '0; dd_ra_voice <= '0; dd_f1_voice <= '0;
        dd_tp_exp <= '0; dd_tp_seen <= '0; dd_ra_accum <= '0;
        dd_ra_cr <= '0; dd_f1_reg <= '0; dd_f1_bank <= 1'b0;
        dd_tp_frame <= '0; dd_ra_frame <= '0;
        dd_f1_frame <= '0; dd_f2_frame <= '0;
        dd_f0_cnt <= '0; dd_wj_cnt <= '0; dd_ac_cnt <= '0;
        dd_wj_voice <= '0; dd_ac_voice <= '0;
        dd_wj_snap <= '0; dd_wj_new <= '0;
        dd_wj_start <= '0; dd_wj_end <= '0; dd_ac_data <= '0;
    end else if (frame_pulse) begin
        dd_f0_cnt <= det_f0_cnt; dd_wj_cnt <= det_wj_cnt;
        dd_ac_cnt <= det_ac_cnt;
        dd_wj_voice <= det_wj_voice; dd_ac_voice <= det_ac_voice;
        dd_wj_snap <= det_wj_snap; dd_wj_new <= det_wj_new;
        dd_wj_start <= det_wj_start; dd_wj_end <= det_wj_end;
        dd_ac_data <= det_ac_data;
        dd_tp_cnt <= det_tp_cnt; dd_ra_cnt <= det_ra_cnt;
        dd_f1_cnt <= det_f1_cnt; dd_f2_cnt <= det_f2_cnt;
        dd_cs_cnt <= det_cs_cnt; dd_f3_cnt <= det_f3_cnt;
        dd_f4_cnt <= det_f4_cnt; dd_df_cnt <= det_df_cnt;
        dd_cx_cnt <= det_cx_cnt; dd_bk_cnt <= det_bk_cnt;
        dd_se_cnt <= det_se_cnt; dd_pq_cnt <= det_pq_cnt;
        dd_tp_voice <= det_tp_voice; dd_ra_voice <= det_ra_voice;
        dd_f1_voice <= det_f1_voice;
        dd_tp_exp <= det_tp_exp; dd_tp_seen <= det_tp_seen;
        dd_ra_accum <= det_ra_accum; dd_ra_cr <= det_ra_cr;
        dd_f1_reg <= det_f1_reg; dd_f1_bank <= det_f1_bank;
        dd_tp_frame <= det_tp_frame; dd_ra_frame <= det_ra_frame;
        dd_f1_frame <= det_f1_frame; dd_f2_frame <= det_f2_frame;
    end
end

always_ff @(posedge clk) begin
    if (rst) begin
        c_ticks <= '0; c_under <= '0; c_commit <= '0; c_hostwr <= '0;
        c_hostrd <= '0; c_iset <= '0; c_cesnd <= '0; c_p4req <= '0;
        c_g64 <= '0; c_g128 <= '0; c_g256 <= '0; c_latmaxf <= '0;
        t_under <= '0; t_p4 <= '0; t_tick <= '0;
        latmax_sticky <= '0; lat_last <= '0;
        c_lmin <= 16'sh7fff; c_lmax <= 16'sh8000;
        c_rmin <= 16'sh7fff; c_rmax <= 16'sh8000;
        last_irq_voice <= '0;
        disp_frame <= '0;
        disp_ticks <= '0; disp_under <= '0; disp_commit <= '0;
        disp_hostwr <= '0; disp_hostrd <= '0; disp_iset <= '0;
        disp_g64 <= '0; disp_g128 <= '0; disp_g256 <= '0; disp_latmaxf <= '0;
        disp_cesnd <= '0; disp_p4req <= '0;
        disp_undert <= '0; disp_p4tot <= '0; disp_ticktot <= '0; disp_run <= '0;
        disp_al <= '0; disp_ar <= '0;
        disp_lmin <= '0; disp_lmax <= '0; disp_rmin <= '0; disp_rmax <= '0;
        disp_av <= '0; disp_irqv <= '0; disp_pg <= '0; disp_irqn <= 1'b1;
    end else begin
        if (sample_tick) begin
            c_ticks <= c_ticks + 1'd1;
            t_tick  <= t_tick + 1'd1;
            if (audio_l < c_lmin) c_lmin <= audio_l;
            if (audio_l > c_lmax) c_lmax <= audio_l;
            if (audio_r < c_rmin) c_rmin <= audio_r;
            if (audio_r > c_rmax) c_rmax <= audio_r;
        end
        if (under_edge) begin
            c_under <= c_under + 1'd1;
            t_under <= t_under + 1'd1;
        end
        if (commit)      c_commit <= c_commit + 1'd1;
        if (hostwe_edge) c_hostwr <= c_hostwr + 1'd1;
        if (hostre_edge) c_hostrd <= c_hostrd + 1'd1;
        if (irq_set) begin
            c_iset <= c_iset + 1'd1;
            last_irq_voice <= irq_voice;
        end
        if (ce_snd) c_cesnd <= c_cesnd + 1'd1;
        if (p4_done) begin
            c_p4req <= c_p4req + 1'd1;
            t_p4    <= t_p4 + 1'd1;
            lat_last <= lat_now;
            if (lat_now > latmax_sticky) latmax_sticky <= lat_now;
            if (lat_now > c_latmaxf)     c_latmaxf <= lat_now;
            if (lat_now >= 16'd64)  c_g64  <= c_g64 + 1'd1;
            if (lat_now >= 16'd128) c_g128 <= c_g128 + 1'd1;
            if (lat_now >= 16'd256) c_g256 <= c_g256 + 1'd1;
        end

        if (frame_pulse) begin
            disp_frame  <= disp_frame + 1'd1;
            disp_ticks  <= c_ticks;    c_ticks  <= '0;
            disp_under  <= c_under;    c_under  <= '0;
            disp_commit <= c_commit;   c_commit <= '0;
            disp_hostwr <= c_hostwr;   c_hostwr <= '0;
            disp_hostrd <= c_hostrd;   c_hostrd <= '0;
            disp_iset   <= c_iset;     c_iset   <= '0;
            disp_cesnd  <= c_cesnd;    c_cesnd  <= '0;
            disp_p4req  <= c_p4req;    c_p4req  <= '0;
            disp_g64    <= c_g64;      c_g64    <= '0;
            disp_g128   <= c_g128;     c_g128   <= '0;
            disp_g256   <= c_g256;     c_g256   <= '0;
            disp_latmaxf<= c_latmaxf;  c_latmaxf<= '0;
            disp_lmin   <= c_lmin;     c_lmin   <= 16'sh7fff;
            disp_lmax   <= c_lmax;     c_lmax   <= 16'sh8000;
            disp_rmin   <= c_rmin;     c_rmin   <= 16'sh7fff;
            disp_rmax   <= c_rmax;     c_rmax   <= 16'sh8000;
            disp_undert <= t_under;
            disp_p4tot  <= t_p4;
            disp_ticktot<= t_tick;
            disp_run    <= run_mask;
            disp_al     <= audio_l;
            disp_ar     <= audio_r;
            disp_av     <= active_voices;
            disp_pg     <= current_page;
            disp_irqn   <= irq_n;
            disp_irqv   <= last_irq_voice;
        end
    end
end

// ---------------------------------------------------------------------------
// Host commit log: newest-first 12-entry shift chain, display copy latched
// per frame so a screenshot never shows a mid-shift mixture.
// ---------------------------------------------------------------------------
typedef struct packed {
    logic [6:0]  page;
    logic [3:0]  regn;
    logic [31:0] data;
} logent_t;
logent_t log_q [0:11];
logent_t disp_log [0:11];
always_ff @(posedge clk) begin
    if (rst) begin
        for (int i = 0; i < 12; i++) begin
            log_q[i] <= '0;
            disp_log[i] <= '0;
        end
    end else begin
        if (commit) begin
            log_q[0] <= {commit_page, commit_reg, commit_data};
            for (int i = 1; i < 12; i++) log_q[i] <= log_q[i-1];
        end
        if (frame_pulse)
            for (int i = 0; i < 12; i++) disp_log[i] <= log_q[i];
    end
end

// ---------------------------------------------------------------------------
// Text grid position. Cells are 4 px wide (hcnt[1:0] inside), 6 lines tall.
// Divide-by-6 via multiply: vcnt*683 >> 12 is exact for 0..261.
// ---------------------------------------------------------------------------
wire [6:0] tcol = hcnt[8:2];
wire [1:0] gx   = hcnt[1:0];
// Low 12 bits of the products are the discarded fixed-point fraction.
/* verilator lint_off UNUSEDSIGNAL */
wire [19:0] vprod = vcnt * 20'd683;
wire [19:0] vnprod = vnext * 20'd683;
/* verilator lint_on UNUSEDSIGNAL */
wire [5:0] trow  = vprod[17:12];
wire [2:0] tline = 3'(vcnt - 9'({trow, 1'b0}) - 9'({trow, 2'b00})); // vcnt-trow*6

// Prefetch next line's voice record during this line's blanking.
wire [8:0] vnext = vcnt + 9'd1;
wire [5:0] nrow = vnprod[17:12];
logic pf1, pf2;
logic [7:0]      vnum_r;
logic [REC_W-1:0] vrec;
always_ff @(posedge clk) begin
    pf1 <= 1'b0;
    pf2 <= pf1;
    if (ce_pixel && (hcnt == active_width)) begin
        if (nrow >= 6'd5 && nrow <= 6'd36) begin
            shadow_rd_addr <= 5'(nrow - 6'd5);
            pf1 <= 1'b1;
        end
    end
    if (pf2) begin
        vrec   <= shadow_q;
        vnum_r <= {3'd0, shadow_rd_addr};
    end
end

