wire [14:0] grow = glyph(charcode);
logic [2:0] gslice;
always_comb begin
    case (tline)
        3'd0: gslice = grow[14:12];
        3'd1: gslice = grow[11:9];
        3'd2: gslice = grow[8:6];
        3'd3: gslice = grow[5:3];
        3'd4: gslice = grow[2:0];
        default: gslice = 3'd0;
    endcase
end
wire pix = (gx != 2'd3) && gslice[2'd2 - gx];

wire in_active = (hcnt < active_width) && (vcnt < active_height);

logic [23:0] rgb_r;
always_ff @(posedge clk) begin
    if (ce_pixel)
        rgb_r <= (en && in_active && pix) ? 24'hffffff : 24'h000000;
end

assign rgb_out = en ? rgb_r : rgb_in;

endmodule
